package extractor_test

import (
	"bytes"
	"crypto/sha256"
	"fmt"
	"io"
	"os"
	"testing"
)

// checkOutput validates the circuit generated by the extractor against its
// golden file. Set GNARK_LEAN_UPDATE_GOLDENS=1 to refresh every exercised file.
func checkOutput(t *testing.T, testOutput string) {
	// I assume tests are executed from the extractor/test directory
	filename := fmt.Sprintf("../../test/%s.lean", t.Name())

	if _, err := os.Stat(filename); err != nil {
		t.Fatalf("required extractor golden %s is missing or unreadable: %v", filename, err)
	}
	if os.Getenv("GNARK_LEAN_UPDATE_GOLDENS") == "1" {
		if err := os.WriteFile(filename, []byte(testOutput), 0o644); err != nil {
			t.Fatalf("refresh extractor golden %s: %v", filename, err)
		}
		return
	}

	f, err := os.Open(filename)
	if err != nil {
		t.Fatalf("error checking test output\n\n%s\n\n%s\n\n", err, testOutput)
	}
	defer f.Close()

	h := sha256.New()
	if _, err := io.Copy(h, f); err != nil {
		t.Fatal(err)
	}

	correctHash := h.Sum(nil)

	h.Reset()
	if _, err := h.Write([]byte(testOutput)); err != nil {
		t.Fatal(err)
	}
	testResultHash := h.Sum(nil)
	if !bytes.Equal(correctHash, testResultHash) {
		t.Logf("This circuit doesn't match the result in the test folder\n\n%s", testOutput)
		t.Fail()
	}
}
